#include "stm32f4xx.h"

void led_init(void) {
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIODEN;
    GPIOD->MODER &= ~(3U << (12 * 2));
    GPIOD->MODER |=  (1U << (12 * 2));
    GPIOD->OTYPER &= ~(1U << 12);
    GPIOD->PUPDR &= ~(3U << (12 * 2));
    GPIOD->BSRR = (1U << 12);
}

